const setApplicationStatus = `-- name: SetApplicationStatus :execrows
UPDATE applications
SET status = $1,
    decided_at = CASE WHEN $1::text IN ('offered', 'rejected') THEN now() ELSE decided_at END
WHERE id = $2 AND status = $3
`

type SetApplicationStatusParams struct {
	ToStatus   string
	ID         uuid.UUID
	FromStatus string
}

// Moves from one status to another; 0 rows if it was not in @from_status.
// The trigger refuses any move not in application_transitions.
func (q *Queries) SetApplicationStatus(ctx context.Context, arg SetApplicationStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setApplicationStatus, arg.ToStatus, arg.ID, arg.FromStatus)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const staffCountApplications = `-- name: StaffCountApplications :one
SELECT count(*)
FROM applications a
JOIN applicants ap ON ap.id = a.applicant_id
WHERE a.submitted_at IS NOT NULL
  AND ($1::text IS NULL OR a.status = $1)
  AND ($2::uuid IS NULL OR a.programme_id = $2)
  AND ($3::uuid IS NULL OR a.intake_id = $3)
  AND ($4::uuid IS NULL OR a.assigned_to = $4)
  AND (NOT $5::boolean OR a.assigned_to IS NULL)
  AND ($6::text IS NULL
       OR a.reference ILIKE '%' || $6 || '%'
       OR (ap.first_name || ' ' || ap.middle_name || ' ' || ap.last_name) ILIKE '%' || $6 || '%'
       OR ap.email ILIKE '%' || $6 || '%'
       OR ap.phone ILIKE '%' || $6 || '%')
`

type StaffCountApplicationsParams struct {
	Status      *string
	ProgrammeID *uuid.UUID
	IntakeID    *uuid.UUID
	AssignedTo  *uuid.UUID
	Unassigned  bool
	Search      *string
}

func (q *Queries) StaffCountApplications(ctx context.Context, arg StaffCountApplicationsParams) (int64, error) {
	row := q.db.QueryRow(ctx, staffCountApplications,
		arg.Status,
		arg.ProgrammeID,
		arg.IntakeID,
		arg.AssignedTo,
		arg.Unassigned,
		arg.Search,
	)
	var count int64
	err := row.Scan(&count)
	return count, err
}

